def total_price(items, tax_rate):
	subtotal = sum(item.price for item in items)
	return subtotal * (1 + tax_rate)

def find_user(users, email):
	for user in users:
		if user['email'] == email:
			return user
	return None

def write_report(report, output_path):
	with open(output_path, 'w') as output_file:
		output_file.write(report)

def reset_counters(counters):
	for key in counters:
		counters[key] = 0

def parse_port(text):
	port = int(text)
	if port < 1 or port > 65535:
		raise ValueError('the port is outside 1 to 65535')
	return port

def read_config(config_path):
	if not config_path.exists():
		raise FileNotFoundError(config_path)
	return config_path.read_text()

def divide(numerator, denominator):
	if denominator == 0:
		raise ZeroDivisionError('the denominator is zero')
	return numerator / denominator

def delete_record(table, record_id):
	if record_id not in table:
		raise KeyError(record_id)
	del table[record_id]

def build_query(table_name, filters, order_by=None, limit=None):
	query = f'SELECT * FROM {table_name}'
	if filters:
		query += ' WHERE ' + ' AND '.join(filters)
	if order_by is not None:
		query += f' ORDER BY {order_by}'
	if limit is not None:
		query += f' LIMIT {limit}'
	return query

def retry(call, attempt_count=3, delay_seconds=1.0):
	for attempt in range(attempt_count):
		try:
			return call()
		except ConnectionError:
			if attempt == attempt_count - 1:
				raise
			time.sleep(delay_seconds)

def group_by_day(events, timezone_name):
	grouped = {}
	for event in events:
		day = event.timestamp.astimezone(timezone_name).date()
		grouped.setdefault(day, []).append(event)
	return grouped

def average_latency(samples):
	if not samples:
		return 0.0
	return sum(samples) / len(samples)

def load_token(store, key_name):
	token = store.get(key_name)
	if token is None:
		raise LookupError(key_name)
	return token

def rotate_log(log_path, keep_count=5):
	for index in range(keep_count - 1, 0, -1):
		older = log_path.with_suffix(f'.{index}')
		if older.exists():
			older.rename(log_path.with_suffix(f'.{index + 1}'))
